def search(nums, target):
    for idx, v in enumerate(nums):
        if v == target:
            print('found at', idx)
            break
    else:
        print('not found:', target)

search([5, 7, 9], 9)
# found at 2
search([5, 7, 9], 1)
# not found: 1

rows = [('a', 1), ('b', 2), ('a', 3)]

totals = {}
for k, v in rows:
    totals[k] = totals.get(k, 0) + v
print(totals)
# {'a': 4, 'b': 2}

from collections import defaultdict
grouped = defaultdict(list)
for k, v in rows:
    grouped[k].append(v)
print(dict(grouped))
# {'a': [1, 3], 'b': [2]}

n = 29
if n < 2:
    print(n, 'not prime')
else:
    for d in range(2, int(n ** 0.5) + 1):
        if n % d == 0:
            print(n, 'not prime, divisible by', d)
            break
    else:
        print(n, 'prime')
# 29 prime

Teen cheezein: (1) `n < 2` guard (0 aur 1 prime nahi), (2) sirf √n tak check — `int(n ** 0.5) + 1` (29 ke liye range(2, 6) = 2,3,4,5), (3) `break` na hone par `else` → prime.

def first_valid(rows, validate):
    for row in rows:
        if validate(row):
            return row
    else:
        return None
